import{_ as t,o as e,c as i,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"ko/cli/run.md","filePath":"ko/cli/run.md","lastUpdated":1784903584000}'),l={name:"ko/cli/run.md"};function r(o,a,n,s,h,c){return e(),i("div",null,[...a[0]||(a[0]=[d('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="목적" tabindex="-1">목적 <a class="header-anchor" href="#목적" aria-label="Permalink to &quot;목적&quot;">​</a></h2><p>대화형 <strong>TUI(터미널 사용자 인터페이스)</strong> API 탐색기를 실행합니다. 터미널을 떠나지 않고 API 엔드포인트를 검색, 탐색, 검사, 호출할 수 있는 전체 화면 애플리케이션입니다.</p><h2 id="사용-시기" tabindex="-1">사용 시기 <a class="header-anchor" href="#사용-시기" aria-label="Permalink to &quot;사용 시기&quot;">​</a></h2><ul><li>API를 대화형으로 탐색하려고 할 때</li><li>모든 spec에서 특정 엔드포인트를 검색해야 할 때</li><li>spec → collection → tag → endpoint 계층 구조를 탐색하려고 할 때</li><li>MCP 서버를 설정하기 전에 API 호출을 테스트하려고 할 때</li></ul><h2 id="구문" tabindex="-1">구문 <a class="header-anchor" href="#구문" aria-label="Permalink to &quot;구문&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="인수" tabindex="-1">인수 <a class="header-anchor" href="#인수" aria-label="Permalink to &quot;인수&quot;">​</a></h2><table tabindex="0"><thead><tr><th>인수</th><th>위치</th><th>필수</th><th>설명</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>아니요</td><td>워크스페이스 디렉토리. 생략 시 경로 해결 규칙에 따라 결정됩니다.</td></tr></tbody></table><h2 id="플래그" tabindex="-1">플래그 <a class="header-anchor" href="#플래그" aria-label="Permalink to &quot;플래그&quot;">​</a></h2><p>없음.</p><h2 id="모드" tabindex="-1">모드 <a class="header-anchor" href="#모드" aria-label="Permalink to &quot;모드&quot;">​</a></h2><h3 id="검색-모드" tabindex="-1">검색 모드 <a class="header-anchor" href="#검색-모드" aria-label="Permalink to &quot;검색 모드&quot;">​</a></h3><p>모든 spec의 모든 엔드포인트에 대한 전문 검색입니다. HTTP 메서드, 태그, 경로별 필터링을 지원합니다.</p><ul><li>쿼리를 입력하여 엔드포인트 이름, 경로, 설명 검색</li><li>메서드(GET, POST, PUT, DELETE 등)로 결과 필터링</li><li>한 번의 키 입력으로 엔드포인트 세부 정보 보기</li></ul><h3 id="탐색-모드" tabindex="-1">탐색 모드 <a class="header-anchor" href="#탐색-모드" aria-label="Permalink to &quot;탐색 모드&quot;">​</a></h3><p>Spec 계층 구조를 통한 트리 탐색:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>트리를 따라 내려가 특정 엔드포인트 찾기</li><li>엔드포인트 세부 정보 보기 (매개변수, 요청 본문, 응답)</li><li>TUI에서 직접 API 호출</li></ul><h2 id="탐색" tabindex="-1">탐색 <a class="header-anchor" href="#탐색" aria-label="Permalink to &quot;탐색&quot;">​</a></h2><table tabindex="0"><thead><tr><th>키</th><th>동작</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>위/아래 이동</td></tr><tr><td><code>Enter</code></td><td>선택 또는 열기</td></tr><tr><td><code>Esc</code></td><td>뒤로 가기</td></tr><tr><td><code>Tab</code></td><td>검색과 탐색 모드 간 전환</td></tr><tr><td><code>/</code></td><td>검색 입력 포커스</td></tr><tr><td><code>q</code></td><td>종료</td></tr></tbody></table><h2 id="명령-후-검증" tabindex="-1">명령 후 검증 <a class="header-anchor" href="#명령-후-검증" aria-label="Permalink to &quot;명령 후 검증&quot;">​</a></h2><p>TUI는 워크스페이스에서 모든 spec을 로드합니다. spec 로드에 실패하면 인터페이스에 오류 메시지가 표시됩니다.</p><h2 id="세부-사항" tabindex="-1">세부 사항 <a class="header-anchor" href="#세부-사항" aria-label="Permalink to &quot;세부 사항&quot;">​</a></h2><ul><li><strong>자동 초기화:</strong> 설정 파일이 없으면 <code>run</code>이 자동으로 init 마법사를 먼저 실행합니다.</li><li><strong>플래그 없음:</strong> <code>run</code> 명령어에는 플래그가 없습니다 — 모든 설정은 워크스페이스에서 가져옵니다.</li><li><strong>터미널 크기:</strong> TUI는 최소 80×24 문자의 터미널이 필요합니다. 매우 작은 터미널에서는 올바르게 렌더링되지 않을 수 있습니다.</li><li><strong>의존성:</strong> TUI는 Bubbletea를 사용합니다. SSH 및 대부분의 터미널 에뮬레이터에서 작동합니다.</li></ul>',25)])])}const b=t(l,[["render",r]]);export{u as __pageData,b as default};
